-- ============================================================================
--  FWO  |  Rare Loot Pools + Gold Modifier  |  rebuild of script 20513 (Death)
-- ============================================================================
--  Hero points (unchanged) + Gold modifier + five rare loot pools. Slot 1 (the
--  mob's normal treasure drop) is untouched. Rares that hit drop together in ONE
--  bag AT THE KILLER's feet (clear of the corpse's normal loot bag). Dials live
--  in gameevent.Status (0=OFF); set them with ServerConfiguration.bat.
--    999 Hero  998 Gold  993 Slot2  992 Slot3  991 Slot4  990 Slot5  989 Slot6
--  Everything ships OFF except hero(1x). SUPERSEDES 20513_import.sql.
--
--  APPLY:  cd C:\fwo-docker
--    docker exec -i fwo-db mysql -uroot -pejair0xx fwworlddevdb < database\20513_loot_import.sql
--    docker-compose restart fwo-server
-- ============================================================================

INSERT INTO `gameevent` (`ID`,`Description`,`Status`) VALUES
  (999,'Hero Mob-Kill Multiplier',1),
  (998,'Gold Modifier (mob lvl x N)',0),
  (993,'Rare Slot2 Armor/Bracers/Greaves',0),
  (992,'Rare Slot3 Staff/Bow/Amulets',0),
  (991,'Rare Slot4 Saber/Sword/Rings/Shoulders/Masks',0),
  (990,'Rare Slot5 Rare Components',0),
  (989,'Rare Slot6 Heavenly Components',0)
  ON DUPLICATE KEY UPDATE `ID`=`ID`;

UPDATE `script` SET `Data`, `Size`=30846 WHERE `ScriptID`=20513;
